def landscape_jsx(jsx: str, fn_by_id: dict[str, str], ids: list[str]) -> tuple[str, dict[str, str]]:
    """Append <fn>L builders for the requested ids and return the JSX plus the id -> landscape function map."""
    extra, mapping = [], {}
    for template_id in ids:
        fn = fn_by_id.get(template_id)
        if fn not in LAYOUTS:
            continue
        start = jsx.index("function " + fn + "(")
        end = jsx.index("\nfunction ", start + 1)
        body = jsx[start:end].replace("function " + fn + "(", "function " + fn + "L(", 1)
        for old, new in LAYOUTS[fn]:
            if old not in body:
                raise ValueError(f"{fn}: layout anchor missing: {old}")
            body = body.replace(old, new)
        extra.append(body)
        mapping[template_id] = fn + "L"
    anchor = "var FN={"
    return jsx.replace(anchor, "\n".join(extra) + "\n" + anchor, 1), mapping
